namespace Framework.AI.Actions
{
    /// <summary>
    /// エージェントの行動が終了した理由を表す。
    /// </summary>
    public enum AgentActionExitReason
    {
        /// <summary>
        /// 行動が正常に完了した。
        /// </summary>
        Succeeded = 0,

        /// <summary>
        /// 行動の実行に失敗した。
        /// </summary>
        Failed = 1,

        /// <summary>
        /// 別の行動への切り替えによって中断された。
        /// </summary>
        Interrupted = 2,

        /// <summary>
        /// 外部からの要求によって停止された。
        /// </summary>
        Cancelled = 3,

        /// <summary>
        /// 実行中に例外が発生した。
        /// </summary>
        Faulted = 4
    }
}
